import lack from './lack.json'
import lackCoffee from './lack-coffee.json'
import lackTv from './lack-tv.json'
import catalog from './catalog.json'
import flatpack from './catalog-flatpack.json'

// Hand-made guides, bundled with the app. Each JSON is generated by a scripts/gen-*.mjs.
export const products: Record<string, unknown> = {
  lack: lack,
  'lack-coffee': lackCoffee,
  'lack-tv': lackTv,
}

export const productIds = Object.keys(products)
export const DEFAULT_PRODUCT = 'lack'

/** Display names for the picker, without parsing every product up front. */
export const productNames: Record<string, string> = {
  lack: lack.product.name,
  'lack-coffee': lackCoffee.product.name,
  'lack-tv': lackTv.product.name,
}

// Generated guides, fetched from public/products/ on demand:
// IKEA-Manual meshes (scripts/import-ikea-manual.mjs) and simplified flat-pack boxes (scripts/gen-flatpack.mjs).
export interface CatalogEntry {
  id: string
  name: string
  category: string
  steps: number
  timed: boolean
  from: 'ikea-manual' | 'flatpack'
}
export const generated: CatalogEntry[] = [
  ...flatpack.map((c) => ({ ...c, from: 'flatpack' as const })),
  ...catalog.map((c) => ({ ...c, from: 'ikea-manual' as const })),
]

export function pickProduct(id: string | null): string {
  return id && (id in products || generated.some((c) => c.id === id)) ? id : DEFAULT_PRODUCT
}

/** The raw product data: bundled, or fetched for generated guides. */
export async function loadProduct(id: string): Promise<unknown> {
  if (id in products) return products[id]
  const res = await fetch(`${import.meta.env.BASE_URL}products/${id}.json`)
  if (!res.ok) throw new Error(`product ${id}: ${res.status}`)
  return res.json()
}
